const lead = $json || {};
const clean = (value, max = 2000) => String(value ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const email = clean(lead.email, 320).toLowerCase();
const emailDomain = email.split('@')[1] || '';

const reservedDomains = new Set([
  'example.com', 'example.org', 'example.net', 'test.com',
  'localhost', 'invalid'
]);

const emailSyntaxValid =
  String(lead.email_validation_status || '').toLowerCase() === 'syntax_valid'
  && /^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$/i.test(email)
  && !/[\r\n]/.test(email);

const reservedOrInvalidDomain =
  reservedDomains.has(emailDomain)
  || emailDomain.endsWith('.invalid')
  || emailDomain.endsWith('.test')
  || emailDomain.endsWith('.localhost');

const doNotContact = lead.do_not_contact === true
  || String(lead.do_not_contact).toLowerCase() === 'true';
const attempts = Math.max(0, Number(lead.outreach_attempts || 0));
const attemptNumber = Math.min(attempts + 1, 3);
const reasons = [];

if (!email) reasons.push('missing_email');
else if (!emailSyntaxValid) reasons.push('email_not_syntax_valid');
if (reservedOrInvalidDomain) reasons.push('reserved_or_test_email_domain');
if (doNotContact) reasons.push('do_not_contact');
if (attempts >= 3) reasons.push('maximum_outreach_attempts_reached');
if (String(lead.status || '').toLowerCase() !== 'ready_for_outreach') reasons.push('lead_not_ready_for_outreach');
if (String(lead.next_workflow || '') !== '03 - Personalized Email Outreach') reasons.push('lead_not_routed_to_workflow_03');
if (String(lead.lead_priority || '').toLowerCase() !== 'high') reasons.push('lead_not_high_priority');
if (Number(lead.qualification_score || 0) < 80) reasons.push('qualification_score_below_80');

const contactName = clean(lead.contact_name, 300);
const contactFirstName = contactName && lead.decision_maker_status === 'verified' ? contactName.split(' ')[0] : '';
const outreachId = `outreach-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
const job = $('Mark Outreach Job Running').first().json || {};
const personalizationPoints = Array.isArray(lead.personalization_points)
  ? lead.personalization_points.map((value) => clean(value, 500)).filter(Boolean).slice(0, 5)
  : [];
const needSignals = Array.isArray(lead.need_signals)
  ? lead.need_signals.map((value) => clean(value, 500)).filter(Boolean).slice(0, 5)
  : [];

return {
  json: {
    ...lead,
    job_id: job.job_id || '',
    email,
    outreach_id: outreachId,
    outreach_attempt_number: attemptNumber,
    contact_first_name: contactFirstName,
    outreach_allowed: reasons.length === 0,
    outreach_block_reason: reasons.join('; '),
    outreach_started_at: new Date().toISOString(),
    outreach_context: {
      audit_findings: Array.isArray(lead.audit_findings) ? lead.audit_findings : [],
      company_name: clean(lead.company_name, 300),
      contact_name: contactName,
      contact_first_name: contactFirstName,
      job_title: clean(lead.job_title, 200),
      email,
      website: clean(lead.website, 2000),
      domain: clean(lead.domain, 300),
      industry: clean(lead.industry, 200),
      city: clean(lead.city, 200),
      country: clean(lead.country, 120),
      qualification_score: Number(lead.qualification_score || 0),
      lead_priority: clean(lead.lead_priority, 30),
      company_summary: clean(lead.company_summary, 1500),
      website_condition: clean(lead.website_condition, 100),
      primary_need: clean(lead.primary_need, 1000),
      need_signals: needSignals,
      personalization_points: personalizationPoints,
      recommended_service: clean(lead.recommended_service, 300),
      outreach_angle: clean(lead.outreach_angle, 1000),
      qualification_reason: clean(lead.qualification_reason, 1000)
    }
  }
};

const data = $json || {};
const context = data.outreach_context || {};

const prompt = `Write the first cold outreach email from CodeNativeX to this business lead.

GOAL
Start a relevant business conversation and offer one CodeNativeX service that matches the evidence. Ask permission to send a free short breakdown with practical fixes. Do not include a report, attachment, booking link or call CTA in this first email.

WRITING RULES
- Write in natural professional English.
- Subject: 3 to 8 words, specific, no clickbait, no "Re:" or "Fwd:".
- Body: 60 to 120 words before the signature.
- Use the person's first name when available; otherwise use "Hello".
- Use only facts in the supplied context.
- If evidence is uncertain, frame the need as a question or possibility.
- Do not claim that you visited or audited something unless the context proves it.
- Do not invent revenue, employee count, role, technology, pain, or urgency.
- Do not use hype, emojis, guaranteed results, pricing, fake familiarity, or multiple CTAs.
- Mention only one main service.
- Do not add a signature, website URL, or opt-out line; the workflow adds these.
- Mention only verified observations from audit_findings; never invent loading times or enquiry losses.
- If no verified website findings exist, do not pretend a website audit was performed.
- End with: Would you like me to send it over? No cost or obligation.
- Return strict JSON only, with no Markdown.

LEAD CONTEXT
${JSON.stringify(context, null, 2)}

RETURN EXACTLY
{
  "subject": "",
  "body": "",
  "personalization_fact": "",
  "service_focus": ""
}`;

return {
  json: {
    ...data,
    email_generation_prompt: prompt
  }
};

const base = $('Build Personalized Email Prompt').all(0)[$itemIndex]?.json || {};
const current = $json || {};

const raw = current.output ?? current.text ?? current.content ?? '';
const rawText = typeof raw === 'string' ? raw : JSON.stringify(raw);

let parsed = {};
let parseError = '';

try {
  const cleaned = rawText
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '');
  const objectMatch = cleaned.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(objectMatch ? objectMatch[0] : cleaned);
} catch (error) {
  parseError = error.message || 'invalid_ai_json';
}

const cleanSubject = (value) => String(value ?? '')
  .replace(/[\r\n]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 80);

const cleanBody = (value) => String(value ?? '')
  .replace(/\r/g, '')
  .split('\n')
  .map((line) => line.replace(/[ \t]+/g, ' ').trim())
  .join('\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim()
  .slice(0, 2500);

const subject = cleanSubject(parsed.subject);
const body = cleanBody(parsed.body);
const wordCount = body ? body.split(/\s+/).filter(Boolean).length : 0;
const combined = `${subject} ${body}`.toLowerCase();

const problems = [];
if (parseError) problems.push('ai_json_parse_failed');
if (!subject) problems.push('missing_subject');
if (!body) problems.push('missing_body');
if (subject.length < 5 || subject.length > 80) problems.push('invalid_subject_length');
if (/^(re|fwd):/i.test(subject)) problems.push('reply_prefix_not_allowed');
if (wordCount < 45 || wordCount > 150) problems.push('invalid_body_word_count');
if (/\[[^\]]+\]|\{\{?[^}]+\}?\}/.test(body)) problems.push('unresolved_placeholder');
if (/guaranteed|100%|double your|triple your|risk[- ]free|act now/i.test(combined)) problems.push('prohibited_claim');
if (current.error || current.errorMessage) problems.push('model_error');

if (/attach(?:ed|ment)|https?:\/\/|calendly|\d+[- ]minute call|\bvideo\b/i.test(body)) problems.push('first_touch_permission_only');
if (/\d+(?:\.\d+)?\s*%|we recently worked|our client/i.test(body)) problems.push('unapproved_proof');
const contentValid = problems.length === 0;
const signature = 'Best,\nCodeNativeX Team\nhttps://codenativex.com';
const optOut = 'If this is not relevant, reply "not interested" and we will not follow up.';
const finalBody = contentValid ? `${body}\n\n${signature}\n\n${optOut}` : '';

return {
  json: {
    ...base,
    email_subject: subject,
    email_body: finalBody,
    email_body_without_signature: body,
    personalization_fact_used: String(parsed.personalization_fact ?? '').replace(/\s+/g, ' ').trim().slice(0, 500),
    service_focus_used: String(parsed.service_focus ?? '').replace(/\s+/g, ' ').trim().slice(0, 300),
    email_word_count: wordCount,
    email_content_valid: contentValid,
    email_generation_error: problems.join('; '),
    ai_raw_output: rawText.slice(0, 10000)
  }
};

const base = $('Parse and Guard AI Email').all(0)[$itemIndex]?.json || {};
const sent = $json || {};
const errorMessage = [
  sent.error?.message,
  sent.error?.description,
  sent.errorMessage,
  sent.description,
  sent.error && sent.message ? sent.message : ''
].filter(Boolean).join(' | ');
const hasError = Boolean(
  !String(sent.id || sent.messageId || '')
  || sent.error
  || sent.errorMessage
  || (sent.httpCode && Number(sent.httpCode) >= 400)
  || (sent.statusCode && Number(sent.statusCode) >= 400)
);
const sentAt = new Date();
const followUpAt = new Date(sentAt.getTime() + (2 * 24 * 60 * 60 * 1000));

return {
  json: {
    ...base,
    outreach_outcome: hasError ? 'send_failed' : 'sent',
    final_status: hasError ? 'outreach_failed' : 'awaiting_reply',
    final_outreach_status: hasError ? 'failed' : 'sent',
    gmail_message_id: hasError ? '' : String(sent.id || sent.messageId || ''),
    gmail_thread_id: hasError ? '' : String(sent.threadId || ''),
    first_outreach_at: hasError ? (base.first_outreach_at || null) : (base.first_outreach_at || sentAt.toISOString()),
    last_outreach_at: hasError ? null : sentAt.toISOString(),
    next_follow_up_at: hasError ? null : followUpAt.toISOString(),
    final_next_workflow: hasError ? '' : '04 - Reply Monitoring & Follow-Up',
    final_error: hasError ? (errorMessage || 'gmail_send_result_ambiguous_manual_review_required') : ''
  }
};

const base = $json || {};
const attempt = Math.max(1, Number(base.outreach_attempt_number || 1));
const canRetry = attempt < 3;
return {
  json: {
    ...base,
    outreach_outcome: 'generation_failed',
    final_status: canRetry ? 'ready_for_outreach' : 'outreach_failed',
    final_outreach_status: 'failed',
    gmail_message_id: '',
    gmail_thread_id: '',
    first_outreach_at: base.first_outreach_at || null,
    last_outreach_at: null,
    next_follow_up_at: null,
    final_next_workflow: canRetry ? '03 - Personalized Email Outreach' : '',
    final_error: base.email_generation_error || 'email_generation_failed'
  }
};

const base = $json || {};

return {
  json: {
    ...base,
    email_subject: '',
    email_body: '',
    outreach_outcome: 'blocked',
    final_status: 'outreach_blocked',
    final_outreach_status: 'blocked',
    gmail_message_id: '',
    gmail_thread_id: '',
    first_outreach_at: null,
    last_outreach_at: null,
    next_follow_up_at: null,
    final_next_workflow: '',
    final_error: base.outreach_block_reason || 'outreach_not_allowed'
  }
};

const outcome = $('Finalize Outreach Outcome').all(0, $runIndex)[$itemIndex]?.json || {};
const update = $json || {};

const message = [
  update.error?.message,
  update.error?.description,
  update.errorMessage,
  update.description
].filter(Boolean).join(' | ');

const hasError = Boolean(
  update.error
  || update.errorMessage
  || (update.httpCode && Number(update.httpCode) >= 400)
  || (update.code && String(update.code).toLowerCase().startsWith('pgrst'))
);

return {
  json: {
    ...outcome,
    lead_update_ok: !hasError,
    lead_update_error: hasError ? (message || 'supabase_lead_update_failed').slice(0, 1500) : ''
  }
};

const result = $('Restore Outreach Result').all(0, $runIndex)[$itemIndex]?.json || {};
const event = $json || {};
const eventError = event.error?.message || event.errorMessage || '';

return {
  json: {
    event_type: 'personalized_email_outreach_completed',
    lead_id: result.id || '',
    outreach_id: result.outreach_id || '',
    company_name: result.company_name || '',
    recipient_email: result.email || '',
    attempt_number: result.outreach_attempt_number || 1,
    outcome: result.outreach_outcome || '',
    status: result.final_status || '',
    outreach_status: result.final_outreach_status || '',
    subject: result.email_subject || '',
    gmail_message_id: result.gmail_message_id || '',
    gmail_thread_id: result.gmail_thread_id || '',
    next_follow_up_at: result.next_follow_up_at || null,
    next_workflow: result.final_next_workflow || '',
    lead_updated: Boolean(result.lead_update_ok),
    lead_update_error: result.lead_update_error || '',
    event_logged: !eventError,
    event_log_error: eventError,
    completed_at: result.completed_at || new Date().toISOString()
  }
};

const job = $('Mark Outreach Job Running').first().json || {};
const allowed = new Set(['intake_completed', 'intake_duplicate']);
const seen = new Set();
const output = [];
for (const item of $input.all()) {
  const row = item.json || {};
  const key = String(row.lead_key || '').trim();
  const status = String(row.intake_status || '').toLowerCase();
  const verificationStatus = String(row.website_verification_status || '').toLowerCase();
  if (!key || !allowed.has(status) || verificationStatus !== 'verified' || seen.has(key)) continue;
  seen.add(key);
  output.push({ json: { job_id: job.job_id || row.job_id || '', lead_key: key } });
}
return output;

const job = $('Mark Outreach Job Running').first().json || {};
const seen = new Set();
const output = [];
for (const item of $input.all()) {
  const lead = item.json || {};
  if (!lead.id || seen.has(lead.id)) continue;
  if (String(lead.status || '').toLowerCase() !== 'ready_for_outreach') continue;
  if (String(lead.next_workflow || '') !== '03 - Personalized Email Outreach') continue;
  seen.add(lead.id);
  output.push({ json: { ...lead, job_id: job.job_id || '' } });
}
return output;

const claimed = $json || {};
const prepared = $('Prepare Outreach Claim').all(0)
  .map((item) => item.json || {})
  .find((item) => String(item.id || '') === String(claimed.id || '')) || {};
return {
  json: {
    ...prepared,
    ...claimed,
    job_id: prepared.job_id || '',
    outreach_id: prepared.outreach_id,
    outreach_attempt_number: prepared.outreach_attempt_number,
    contact_first_name: prepared.contact_first_name,
    outreach_allowed: prepared.outreach_allowed,
    outreach_block_reason: prepared.outreach_block_reason,
    outreach_started_at: prepared.outreach_started_at,
    outreach_context: prepared.outreach_context || {}
  }
};

const job = $('Get Outreach Completion Job').first().json || {};
const allowed = new Set(['intake_completed', 'intake_duplicate']);
const seen = new Set();
const output = [];
for (const item of $input.all()) {
  const row = item.json || {};
  const key = String(row.lead_key || '').trim();
  const status = String(row.intake_status || '').toLowerCase();
  const verificationStatus = String(row.website_verification_status || '').toLowerCase();
  if (!key || !allowed.has(status) || verificationStatus !== 'verified' || seen.has(key)) continue;
  seen.add(key);
  output.push({ json: { job_id: job.job_id || row.job_id || '', lookup_lead_key: key } });
}
return output;

const job = $('Get Outreach Completion Job').first().json || {};
const leadMap = new Map();
for (const item of $input.all()) {
  const row = item.json || {};
  if (row.id) leadMap.set(String(row.id), row);
}
const allLeads = [...leadMap.values()];
const wasOutreachTarget = (lead) => {
  const status = String(lead.status || '').toLowerCase();
  const next = String(lead.next_workflow || '');
  return Boolean(lead.outreach_id)
    || ['ready_for_outreach', 'outreach_preparing', 'awaiting_reply', 'outreach_failed', 'outreach_blocked'].includes(status)
    || next === '03 - Personalized Email Outreach'
    || next === '04 - Reply Monitoring & Follow-Up';
};
const leads = allLeads.filter(wasOutreachTarget);
const countStatus = (status) => leads.filter((lead) => String(lead.status || '').toLowerCase() === status).length;
const active = leads.filter((lead) => ['ready_for_outreach', 'outreach_preparing'].includes(String(lead.status || '').toLowerCase())).length;
const sent = countStatus('awaiting_reply');
const failed = countStatus('outreach_failed');
const blocked = countStatus('outreach_blocked');
const complete = leads.length > 0 && active === 0;

return {
  json: {
    ...job,
    outreach_batch_complete: complete,
    outreach_targeted_leads: leads.length,
    outreach_active_leads: active,
    outreach_sent_leads: sent,
    outreach_failed_leads: failed,
    outreach_blocked_leads: blocked
  }
};

const summary = $json || {};
const sent = Number(summary.outreach_sent_leads || 0);
const hasReplyMonitoring = sent > 0;
const now = new Date().toISOString();
return {
  json: {
    ...summary,
    job_status_next: hasReplyMonitoring ? 'queued' : 'completed',
    job_stage_next: hasReplyMonitoring ? 'reply_monitoring_queued' : 'personalized_outreach_completed_needs_review',
    job_progress_next: hasReplyMonitoring ? 80 : 100,
    job_next_workflow: hasReplyMonitoring ? '04 - Reply Monitoring & Follow-Up' : null,
    job_completed_at: hasReplyMonitoring ? null : now,
    outreach_result_summary: {
      ...(summary.result_summary || {}),
      outreach_targeted_leads: Number(summary.outreach_targeted_leads || 0),
      outreach_sent_leads: sent,
      outreach_failed_leads: Number(summary.outreach_failed_leads || 0),
      outreach_blocked_leads: Number(summary.outreach_blocked_leads || 0),
      outreach_dispatch_status: hasReplyMonitoring ? 'awaiting_reply_monitoring' : 'no_successful_outreach_needs_review'
    }
  }
};

const outcome = $('Prepare Outreach Job Outcome').first().json || {};
return { json: {
  job_id: outcome.job_id,
  event_type: 'personalized_outreach_batch_completed',
  event_status: outcome.job_status_next,
  event_stage: outcome.job_stage_next,
  event_severity: Number(outcome.outreach_failed_leads || 0) > 0 ? 'warning' : 'info',
  event_error_code: null,
  event_message: `Personalized outreach finished: ${outcome.outreach_sent_leads || 0} sent, ${outcome.outreach_failed_leads || 0} failed, ${outcome.outreach_blocked_leads || 0} blocked.`,
  event_payload: outcome.outreach_result_summary || {}
} };

const now = Date.now();
const staleAfterMs = 30 * 60 * 1000;
const output = [];
for (const item of $input.all()) {
  const lead = item.json || {};
  const updated = new Date(lead.updated_at || 0).getTime();
  if (!lead.id || !lead.outreach_id || !Number.isFinite(updated) || now - updated < staleAfterMs) continue;
  output.push({ json: {
    ...lead,
    stale_error: 'Stale outreach claim detected. Automatic resend blocked because Gmail send outcome may be ambiguous.'
  } });
}
return output;

const updated = $json || {};
const source = $('Prepare Stale Outreach Review').all(0)
  .map((item) => item.json || {})
  .find((item) => String(item.id || '') === String(updated.id || '')) || {};
return { json: {
  outreach_id: source.outreach_id || updated.outreach_id || `stale-${source.id || updated.id}`,
  lead_id: source.id || updated.id,
  sequence_no: Math.max(1, Number(source.outreach_attempts || 1)),
  outcome: 'send_failed',
  to_email: source.email || null,
  subject: source.outreach_subject || null,
  message_id: source.gmail_message_id || null,
  thread_id: source.gmail_thread_id || null,
  error_message: source.stale_error || 'Stale outreach claim requires manual review.',
  next_workflow: null
} };
